-- skinanimals | sql/install.sql
--
-- Creates: no tables of its own.
-- Items:   every plain (non-legendary) item config/animals.lua hands out. The legendary trophies are
--          added by legendaryhunt/sql/install.sql; run that too if you use Config.Legendaries.
-- INSERT IGNORE: an item that already exists (many are shared with stores, ranches and fishing)
-- is left exactly as it is. Safe to run more than once.
-- After adding items do a FULL server restart: vorp_inventory caches the items table at startup.

